// src/services/aiSimplifier.ts
function splitSentences(text) {
  return text.split(/(?<=[.!?])\s+/).map((s) => s.trim()).filter((s) => s.length > 10);
}
function simplifyEligibility(text) {
  const bullets = [];
  const lower = text.toLowerCase();
  const expMatch = lower.match(/(\d+)\+?\s*year[s]?\s*(of)?\s*(experience|exp)/);
  if (expMatch) bullets.push(`\u2705 You need ${expMatch[1]}+ years of experience`);
  if (lower.includes("bachelor") || lower.includes("degree"))
    bullets.push("\u2705 A college degree is needed");
  if (lower.includes("student") || lower.includes("undergraduate") || lower.includes("postgraduate"))
    bullets.push("\u2705 Open to students");
  const teamMatch = lower.match(/team[s]? of (\d+)\s*(to|-)\s*(\d+)/);
  if (teamMatch) bullets.push(`\u2705 Teams of ${teamMatch[1]}\u2013${teamMatch[3]} people`);
  if (lower.includes("figma")) bullets.push("\u{1F6E0} Must know Figma");
  if (lower.includes("react")) bullets.push("\u{1F6E0} Must know React");
  if (lower.includes("tensorflow") || lower.includes("pytorch")) bullets.push("\u{1F6E0} Must know ML frameworks");
  if (bullets.length === 0) {
    splitSentences(text).slice(0, 2).forEach((s) => bullets.push(`\u2022 ${s}`));
  }
  return bullets;
}
function summarizeDescription(text) {
  const sentences = splitSentences(text);
  return sentences.slice(0, 3).map((s) => `\u2022 ${s}`);
}
function getWhyGood(title, type) {
  if (type?.toLowerCase().includes("hackathon"))
    return `Great chance to build something cool and win prizes \u{1F3C6}. You will meet other smart people too!`;
  if (type?.toLowerCase().includes("internship"))
    return `This will give you real work experience \u{1F4BC}. A great first step in your career!`;
  return `This is a great opportunity to grow your skills and get noticed by top companies \u{1F31F}.`;
}
function ruleBasedSimplify(raw) {
  return {
    title: raw.title,
    company: raw.company || raw.organization || "Unknown",
    location: raw.location || "Remote / Online",
    whatYouWillDo: summarizeDescription(raw.description),
    whoCanApply: simplifyEligibility(raw.eligibility),
    whyItsGood: getWhyGood(raw.title, raw.type),
    deadline: raw.deadline || "Check the listing",
    badge: raw.prize ? "\u{1F3C6}" : raw.type?.toLowerCase().includes("internship") ? "\u{1F4BC}" : "\u{1F680}"
  };
}
