googleAuthRouter.post("/assessment/complete", AuthService.authenticateToken, async (req, res) => {
  try {
    const { assessment_score, classification, assessment_metrics } = req.body;
    if (typeof assessment_score !== "number" || !Number.isFinite(assessment_score) || assessment_score < 0 || assessment_score > 100 || typeof classification !== "string" || !classification.trim()) {
      return res.status(400).json({ error: "Assessment score and classification are required" });
    }
    await database_default.updateUserAssessment(req.user.userId, {
      assessment_completed: true,
      assessment_score,
      classification,
      assessment_metrics
    });
    let parsedMetrics = {};
    try {
      if (assessment_metrics) {
        parsedMetrics = JSON.parse(assessment_metrics);
      }
    } catch (e) {
      console.error("Error parsing metrics:", e);
    }
    const newResult = new AssessmentResult_default({
      userId: req.user.userId,
      googleId: req.user.googleId,
      score: assessment_score,
      classification,
      metrics: parsedMetrics
    });
    await newResult.save();
    let adaptiveParams = null;
    try {
      const cp = parsedMetrics.cognitiveProfile || parsedMetrics;
      const cognitiveProfile = {
        phonological: cp.phonological || 50,
        visual: cp.visual || 50,
        workingMemory: cp.memory || cp.workingMemory || 50,
        processingSpeed: cp.processing_speed || cp.processingSpeed || 50,
        orthographic: cp.orthographic || 50,
        executive: cp.executive || 50
      };
      adaptiveParams = await initializeMLAdaptiveParams(req.user.userId, cognitiveProfile);
    } catch (mlError) {
      console.warn("\u26A0\uFE0F  ML initialization error (non-critical):", mlError);
    }
    res.json({
      success: true,
      message: "Assessment completed successfully",
      adaptiveParams: adaptiveParams || null
    });
  } catch (error) {
    console.error("Assessment completion error:", error);
    res.status(500).json({ error: "Internal server error" });
  }
});
googleAuthRouter.post("/assessment/retake", AuthService.authenticateToken, async (req, res) => {
  try {
    await database_default.updateUserAssessment(req.user.userId, {
      assessment_completed: false,
      assessment_score: void 0,
      classification: void 0
    });
    res.json({ success: true, message: "Assessment reset successfully" });
  } catch (error) {
    console.error("Assessment retake error:", error);
    res.status(500).json({ error: "Internal server error" });
  }
});
googleAuthRouter.post("/logout", (req, res) => {
  req.logout((err) => {
    if (err) {
      return res.status(500).json({ error: "Logout failed" });
    }
    res.json({ success: true, message: "Logged out successfully" });
  });
});
googleAuthRouter.post("/ml/init-adaptive-params", AuthService.authenticateToken, async (req, res) => {
  try {
    const userId3 = req.user.userId;
    const existingParams = await AdaptiveParams_default.findOne({ userId: userId3 });
    if (existingParams) {
      return res.json({
        success: true,
        message: "Adaptive parameters already initialized",
        params: existingParams.params
      });
    }
    const user = await database_default.getUserById(userId3);
    if (!user || !user.assessment_completed) {
      return res.status(400).json({ error: "User has not completed assessment" });
    }
    let parsedMetrics = {};
    try {
      if (user.assessment_metrics) {
        parsedMetrics = JSON.parse(user.assessment_metrics);
      }
    } catch (e) {
      console.error("Error parsing metrics:", e);
    }
    const cp = parsedMetrics.cognitiveProfile || parsedMetrics;
    const cognitiveProfile = {
      phonological: cp.phonological || 50,
      visual: cp.visual || 50,
      workingMemory: cp.memory || cp.workingMemory || 50,
      processingSpeed: cp.processing_speed || cp.processingSpeed || 50,
      orthographic: cp.orthographic || 50,
      executive: cp.executive || 50
    };
    const adaptiveParams = await initializeMLAdaptiveParams(userId3, cognitiveProfile);
    if (adaptiveParams) {
      res.json({
        success: true,
        message: "Adaptive parameters initialized successfully",
        params: adaptiveParams
      });
    } else {
      res.status(503).json({
        success: false,
        message: "ML service unavailable, but will retry on next session"
      });
    }
  } catch (error) {
    console.error("ML init adaptive params error:", error);
    res.status(500).json({ error: "Internal server error" });
  }
});

